    private static bool HasAnyModule(ProcessSnapshot p, params string[] names) =>
        p.ModuleNames.Any(module => names.Any(name => module.Equals(name, StringComparison.OrdinalIgnoreCase)));

    private static string CategoryFor(ProcessSnapshot p, FrameworkAssessment fw)
    {
        if (fw.Name == global::ProcessLens.Core.SysPulseLocalization.Literal("WSL")) return global::ProcessLens.Core.SysPulseLocalization.Literal("WSL");
        if (fw.Name is ".NET" or "Python" or "Node.js" or "Java/JVM" or "PowerShell") return global::ProcessLens.Core.SysPulseLocalization.Literal("Sviluppo");
        if (p.ServiceNames.Count > 0) return global::ProcessLens.Core.SysPulseLocalization.Literal("Background");
        if (p.ExecutablePath?.StartsWith(Environment.GetFolderPath(Environment.SpecialFolder.Windows), StringComparison.OrdinalIgnoreCase) == true) return global::ProcessLens.Core.SysPulseLocalization.Literal("Windows");
        if (string.Equals(p.ParentName, p.Name, StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Background");
        return global::ProcessLens.Core.SysPulseLocalization.Literal("Applicazioni");
    }

    private static string? Opt(string cmd, string option)
    {
        var m = Regex.Match(cmd, global::ProcessLens.Core.SysPulseLocalization.Concat(Regex.Escape(option),global::ProcessLens.Core.SysPulseLocalization.Literal("=(?:\"([^\"]+)\"|([^\\s]+))")), RegexOptions.IgnoreCase);
        return m.Success ? (m.Groups[1].Success ? m.Groups[1].Value : m.Groups[2].Value) : null;
    }

    private static bool Eq(string? a, string b) => string.Equals(a, b, StringComparison.OrdinalIgnoreCase);
    private static string UtilityRole(string? value)
    {
        string s = value ?? string.Empty;
        if (s.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("Network"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Servizio di rete");
        if (s.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("Audio"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Servizio audio");
        if (s.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("Storage"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Servizio storage");
        if (s.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("Video"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Servizio video");
        if (s.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("NodeService"), StringComparison.OrdinalIgnoreCase) || s.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("Node"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Processo ausiliario Node.js");
        if (s.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("DataDecoder"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Servizio decodifica dati");
        if (s.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("ProxyResolver"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Risolutore proxy");
        if (s.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("Tracing"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Servizio tracing/diagnostica");
        if (s.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("Media"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Servizio multimediale");
        return global::ProcessLens.Core.SysPulseLocalization.Literal("Processo ausiliario");
    }
